64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
71	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
72	     */
73	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        List<String> missingFields = new ArrayList<>();
122	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
123	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
124	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
125	        requireNonBlank(missingFields, "address", normalizedAddress);
126	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
127	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
128	        if (!missingFields.isEmpty()) {
129	            throw new MissingRequiredFieldsException(missingFields);
130	        }
131	        requireDailyLimitNotReached();
132	        requireCityBelowCapacity(ownerFieldsDto.getCity());
133	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
134	        requireUniqueTelephone(normalizedTelephone);
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (!sharesHousehold) {
137	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
138	        }
139	        ownerFieldsDto.setTelephone(normalizedTelephone);
140	        if (ownerFieldsDto.getEmail() != null) {
141	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
142	        }
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        owner.setAddress(normalizedAddress);
146	        if (owner.getRegistrationDate() == null) {
147	            owner.setRegistrationDate(LocalDate.now());
148	        }
149	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
150	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
151	        if (sharesHousehold) {
152	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
153	        }
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
164	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
165	        if (currentOwner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        currentOwner.setAddress(ownerFieldsDto.getAddress());
169	        currentOwner.setCity(ownerFieldsDto.getCity());
170	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
171	        currentOwner.setLastName(ownerFieldsDto.getLastName());
172	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
173	        this.clinicService.saveOwner(currentOwner);
174	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
175	    }
