177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Transactional
179	    @Override
180	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        this.clinicService.deleteOwner(owner);
186	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
187	    }
