189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
192	        Owner owner = this.clinicService.findOwnerById(ownerId);
193	        if (owner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        HttpHeaders headers = new HttpHeaders();
197	        Pet pet = petMapper.toPet(petFieldsDto);
198	        owner.setId(ownerId);
199	        pet.setOwner(owner);
200	        pet.getType().setName(null);
201	        this.clinicService.savePet(pet);
202	        PetDto petDto = petMapper.toPetDto(pet);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
204	            .buildAndExpand(pet.getId()).toUri());
205	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
206	    }
