225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
228	        HttpHeaders headers = new HttpHeaders();
229	        Visit visit = visitMapper.toVisit(visitFieldsDto);
230	        Pet pet = new Pet();
231	        pet.setId(petId);
232	        visit.setPet(pet);
233	        this.clinicService.saveVisit(visit);
234	        VisitDto visitDto = visitMapper.toVisitDto(visit);
235	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
236	            .buildAndExpand(visit.getId()).toUri());
237	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
238	    }
