241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
244	        Owner owner = this.clinicService.findOwnerById(ownerId);
245	        if (owner != null) {
246	            Pet pet = owner.getPet(petId);
247	            if (pet != null) {
248	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
249	            }
250	        }
251	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	    }
253	
254	    /**
255	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
256	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
257	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
258	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
259	     *
260	     * @param city the owner's city (already validated non-blank)
261	     * @param lastName the owner's last name (already validated non-blank)
262	     * @return the formatted customer code for the owner being created
263	     */
264	    private String nextCustomerCode(String city, String lastName) {
265	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
266	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
267	        int sequence = (int) this.clinicService.findAllOwners().stream()
268	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
269	            .count() + 1;
270	        return String.format("%s-%s-%04d", city3, last3, sequence);
271	    }
272	
273	    /**
274	     * Counts the existing owners (those already persisted before this create) whose first and last
275	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
276	     * the new owner as its {@code namesakeCount} and echoed back on reads.
277	     *
278	     * @param firstName the incoming owner's first name (already validated non-blank)
279	     * @param lastName the incoming owner's last name (already validated non-blank)
280	     * @return the number of existing namesakes sharing both names case-insensitively
281	     */
282	    private int countNamesakes(String firstName, String lastName) {
283	        return (int) this.clinicService.findAllOwners().stream()
284	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
285	                && lastName.equalsIgnoreCase(existing.getLastName()))
286	            .count();
287	    }
288	
289	    /**
290	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
291	     * whitespace-only), so the caller can reject the request listing every offending field.
292	     */
293	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
294	        if (value == null || value.isBlank()) {
295	            missingFields.add(fieldName);
296	        }
297	    }
298	
299	    /**
300	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
301	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
302	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
303	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
304	     * {@code "+61412345678"}.
305	     *
306	     * @param telephone the raw telephone value from the request
307	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
308	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
309	     */
310	    private static String normalizeTelephone(String telephone) {
311	        String e164 = toE164(telephone);
312	        if (e164 == null) {
313	            throw new InvalidFieldValueException("telephone",
314	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
315	        }
316	        return e164;
317	    }
318	
319	    /**
320	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
321	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
322	     * owners' stored numbers when detecting duplicates.
323	     */
324	    private static String toE164(String telephone) {
325	        if (telephone == null) {
326	            return null;
327	        }
328	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
329	        String digits;
330	        if (cleaned.startsWith("+")) {
331	            digits = cleaned.substring(1);
332	        } else {
333	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
334	            digits = "61" + national;
335	        }
336	        if (!digits.matches("[0-9]{8,15}")) {
337	            return null;
338	        }
339	        return "+" + digits;
340	    }
341	
342	    /**
343	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
344	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
345	     *
346	     * @param email the raw email value from the request (already known to be non-null)
347	     * @return the lower-cased email to be stored and returned
348	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
349	     */
350	    private static String normalizeEmail(String email) {
351	        String trimmed = email.trim();
352	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
353	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
354	        }
355	        return trimmed.toLowerCase(Locale.ROOT);
356	    }
357	
358	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
359	    private static final int MAX_OWNERS_PER_CITY = 50;
360	
361	    /**
362	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
363	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
364	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
365	     *
366	     * @param city the incoming owner's city (already validated non-blank)
367	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
368	     */
369	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
370	    private static final int MAX_OWNERS_PER_DAY = 100;
371	
372	    /**
373	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
374	     * today, counting existing owners whose {@code registrationDate} equals the current date. New owners
375	     * default to today's {@code registrationDate}, so this caps the number that may be created per day.
376	     *
377	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
378	     */
379	    private void requireDailyLimitNotReached() {
380	        LocalDate today = LocalDate.now();
381	        long registeredToday = this.clinicService.findAllOwners().stream()
382	            .filter(existing -> today.equals(existing.getRegistrationDate()))
383	            .count();
384	        if (registeredToday >= MAX_OWNERS_PER_DAY) {
385	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
386	        }
387	    }
388	
389	    private void requireCityBelowCapacity(String city) {
390	        long cityOwners = this.clinicService.findAllOwners().stream()
391	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
392	            .count();
393	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
394	            throw new CityAtCapacityException(city);
395	        }
396	    }
397	
398	    /**
399	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
400	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
401	     *
402	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
403	     * @throws DuplicateTelephoneException if another owner already uses this telephone
404	     */
405	    private void requireUniqueTelephone(String normalizedTelephone) {
406	        boolean taken = this.clinicService.findAllOwners().stream()
407	            .map(Owner::getTelephone)
408	            .map(OwnerRestControllerV1::toE164)
409	            .filter(existing -> existing != null)
410	            .anyMatch(normalizedTelephone::equals);
411	        if (taken) {
412	            throw new DuplicateTelephoneException(normalizedTelephone);
413	        }
414	    }
415	
416	    /**
417	     * Rejects the request when another owner already shares this household, i.e. has both the same
418	     * last name and the same address once each value is normalized (trimmed, internal whitespace
419	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
420	     * when the request opts in via {@code sharesHousehold}.
421	     *
422	     * @param lastName the incoming owner's last name (already validated non-blank)
423	     * @param address the incoming owner's address (already validated non-blank)
424	     * @throws DuplicateHouseholdException if another owner already has this last name and address
425	     */
426	    private void requireUniqueHousehold(String lastName, String address) {
427	        String normalizedLastName = normalizeForHousehold(lastName);
428	        String normalizedAddress = householdAddressKey(address);
429	        boolean taken = this.clinicService.findAllOwners().stream()
430	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
431	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
432	        if (taken) {
433	            throw new DuplicateHouseholdException(lastName, address);
434	        }
435	    }
436	
437	    /**
438	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
439	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
440	     * comparisons are case-insensitive.
441	     */
442	    private static String normalizeForHousehold(String value) {
443	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
444	    }
445	
446	    /**
447	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
448	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
449	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
450	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
451	     * value normalizes to the empty string, so the required-field check rejects an address that is
452	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
453	     *
454	     * @param address the raw address value from the request (may be {@code null})
455	     * @return the normalized address, or the empty string when blank after normalization
456	     */
457	    private static String normalizeAddress(String address) {
458	        if (address == null) {
459	            return "";
460	        }
461	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
462	        if (collapsed.isEmpty()) {
463	            return "";
464	        }
465	        String[] tokens = collapsed.split(" ");
466	        StringBuilder sb = new StringBuilder();
467	        for (String token : tokens) {
468	            String expanded = switch (token) {
469	                case "ST" -> "STREET";
470	                case "RD" -> "ROAD";
471	                case "AVE" -> "AVENUE";
472	                default -> token;
473	            };
474	            if (sb.length() > 0) {
475	                sb.append(' ');
476	            }
477	            sb.append(expanded);
478	        }
479	        return sb.toString();
480	    }
481	
482	    /**
483	     * Derives the comparison key for an address used by household-duplicate detection and the shared
484	     * household identifier: the address is first put in its canonical normalized form and then
485	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
486	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
487	     */
488	    private static String householdAddressKey(String address) {
489	        return normalizeForHousehold(normalizeAddress(address));
490	    }
491	
492	    /**
493	     * Joins the household identified by this last name and address, returning the stable shared
494	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
495	     * from the normalized last name and address, so every owner in the same household resolves to the
496	     * same value. Any existing household members that predate this feature (or were created without
497	     * opting in) are back-filled with the shared identifier so the whole household agrees.
498	     *
499	     * @param lastName the joining owner's last name (already validated non-blank)
500	     * @param address the joining owner's address (already validated non-blank)
501	     * @return the shared household identifier for this last name and address
502	     */
503	    private String joinHousehold(String lastName, String address) {
504	        String normalizedLastName = normalizeForHousehold(lastName);
505	        String normalizedAddress = householdAddressKey(address);
506	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
507	        this.clinicService.findAllOwners().stream()
508	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
509	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
510	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
511	            .forEach(existing -> {
512	                existing.setHouseholdId(householdId);
513	                this.clinicService.saveOwner(existing);
514	            });
515	        return householdId;
516	    }
517	
518	    /**
519	     * Derives a stable household identifier from the already-normalized last name and address as the
520	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
521	     * always maps to the same identifier.
522	     */
523	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
524	        try {
525	            byte[] digest = MessageDigest.getInstance("SHA-256")
526	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
527	            StringBuilder sb = new StringBuilder();
